//! 🧭️ The closed history transition policy shared with the neutral corpus.

use super::*;
pub(crate) struct Facts<'a>{pub request:&'a str,pub namespace:&'a str,pub intent:&'a str,pub source:&'a str,pub object:&'a str,pub outcome:&'a str,pub segment:&'a str,pub selection:&'a str,pub names:usize,pub bytes:u64,pub segments:usize,pub cancel:&'a str}
pub(crate) fn classify(facts:&Facts<'_>)->Result<&'static str,Error>{
 let closed=[(["inspect","reconcile","rollover"].contains(&facts.request)),(["continuous","rebound","foreign"].contains(&facts.namespace)),(["valid","missing","malformed"].contains(&facts.intent)),(["before","after","absent","foreign"].contains(&facts.source)),(["absent","expected","foreign","unknown"].contains(&facts.object)),(["complete","missing","partial"].contains(&facts.outcome)),(["open","sealed","publishing"].contains(&facts.segment)),(["valid","missing","fork"].contains(&facts.selection)),(["none","before","after"].contains(&facts.cancel))];
 if closed.contains(&false)||facts.names>MAXIMUM_DIRECTORY_ENTRIES||facts.bytes>MAXIMUM_JOURNAL_BYTES||facts.segments>MAXIMUM_SEGMENTS{return Err(error(ErrorKind::Boundary,"","invalid-history-observation"));}
 Ok(if facts.cancel=="before"{"cancelled"}else if facts.namespace=="foreign"||facts.intent!="valid"||facts.selection=="fork"{"quarantined"}else if facts.request=="rollover"{if facts.segments>=MAXIMUM_SEGMENTS{"history-full"}else if facts.selection=="missing"{"selection-required"}else{"segment-selected"}}else if facts.request=="inspect"{if facts.names>=ORDINARY_NAMES||facts.bytes>=ORDINARY_BYTES{"rollover-required"}else{"inspection"}}else if matches!(facts.object,"foreign"|"unknown"){"quarantined"}else if facts.outcome=="complete"{"settled"}else if facts.object=="expected"&&matches!(facts.source,"absent"|"after"){"committed-observed"}else if facts.object=="expected"&&facts.source=="foreign"{"conflict-retained"}else if facts.object=="absent"&&facts.source=="before"{"not-applied"}else{"quarantined"})
}
